-- ── invariants (hand-written) ───────────────────────────────────────────────────────────────────
ALTER TABLE "identity"."identities"
  ADD CONSTRAINT "identities_email_normalised" CHECK ("email" = lower(btrim("email"))),
  ADD CONSTRAINT "identities_email_shape" CHECK (length("email") <= 254 AND "email" ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  ADD CONSTRAINT "identities_status_valid" CHECK ("status" IN ('active', 'disabled')),
  ADD CONSTRAINT "identities_password_is_argon2id" CHECK ("password_hash" IS NULL OR "password_hash" LIKE '$argon2id$%');

ALTER TABLE "identity"."platform_memberships"
  ADD CONSTRAINT "platform_memberships_role_valid" CHECK ("role" IN ('super_admin', 'support', 'verification', 'finance')),
  ADD CONSTRAINT "platform_memberships_status_valid" CHECK ("status" IN ('active', 'deactivated')),
  ADD CONSTRAINT "platform_memberships_deactivation_consistent" CHECK (("status" = 'deactivated') = ("deactivated_at" IS NOT NULL));

-- A session belongs to exactly one membership matching its audience. Customers (P7) get their own column then.
ALTER TABLE "identity"."sessions"
  ADD CONSTRAINT "sessions_audience_valid" CHECK ("audience" IN ('platform', 'merchant', 'agent')),
  ADD CONSTRAINT "sessions_scope_valid" CHECK ("scope" IN ('full', 'mfa_enrollment')),
  ADD CONSTRAINT "sessions_membership_matches_audience" CHECK (
    ("audience" = 'platform' AND "platform_membership_id" IS NOT NULL AND "merchant_membership_id" IS NULL)
    OR ("audience" IN ('merchant', 'agent') AND "merchant_membership_id" IS NOT NULL AND "platform_membership_id" IS NULL)
  ),
  ADD CONSTRAINT "sessions_enrollment_scope_is_platform" CHECK ("scope" = 'full' OR "audience" = 'platform'),
  ADD CONSTRAINT "sessions_expiry_after_creation" CHECK ("absolute_expires_at" > "created_at"),
  ADD CONSTRAINT "sessions_revocation_consistent" CHECK (("revoked_at" IS NULL) = ("revoke_reason" IS NULL));

ALTER TABLE "identity"."refresh_tokens"
  ADD CONSTRAINT "refresh_tokens_hash_is_sha256_hex" CHECK ("token_hash" ~ '^[0-9a-f]{64}$');

ALTER TABLE "identity"."one_time_tokens"
  ADD CONSTRAINT "one_time_tokens_hash_is_sha256_hex" CHECK ("token_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "one_time_tokens_purpose_valid" CHECK ("purpose" IN ('email_verification', 'password_reset'));

ALTER TABLE "identity"."mfa_challenges"
  ADD CONSTRAINT "mfa_challenges_hash_is_sha256_hex" CHECK ("token_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "mfa_challenges_attempts_non_negative" CHECK ("attempts" >= 0);

ALTER TABLE "identity"."recovery_codes"
  ADD CONSTRAINT "recovery_codes_hash_is_sha256_hex" CHECK ("code_hash" ~ '^[0-9a-f]{64}$');

ALTER TABLE "identity"."totp_credentials"
  ADD CONSTRAINT "totp_credentials_step_non_negative" CHECK ("last_used_step" IS NULL OR "last_used_step" >= 0);

ALTER TABLE "tenancy"."merchant_memberships"
  ADD CONSTRAINT "merchant_memberships_kind_valid" CHECK ("kind" IN ('owner', 'staff', 'agent')),
  ADD CONSTRAINT "merchant_memberships_status_valid" CHECK ("status" IN ('active', 'deactivated')),
  ADD CONSTRAINT "merchant_memberships_deactivation_consistent" CHECK (("status" = 'deactivated') = ("deactivated_at" IS NOT NULL));

-- One owner per merchant (OPEN-1 default).
CREATE UNIQUE INDEX "merchant_memberships_one_owner_per_merchant"
  ON "tenancy"."merchant_memberships" ("merchant_id") WHERE "kind" = 'owner';

ALTER TABLE "util"."rate_limit_counters"
  ADD CONSTRAINT "rate_limit_counters_hits_non_negative" CHECK ("hits" >= 0);

-- ── tenancy.merchant_memberships is tenant-owned: RLS like every tenant table (P1) ─────────────
ALTER TABLE "tenancy"."merchant_memberships" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "merchant_memberships_app_own_tenant" ON "tenancy"."merchant_memberships" FOR SELECT TO alphakolect_app
  USING ("merchant_id" = "util"."current_merchant_id"());
CREATE POLICY "merchant_memberships_readonly_all" ON "tenancy"."merchant_memberships" FOR SELECT TO alphakolect_readonly
  USING (true);
-- The app may read its tenant's memberships; creating and changing them is P4 (or the signup function, D2).
GRANT SELECT ON "tenancy"."merchant_memberships" TO alphakolect_app, alphakolect_readonly;
